import{c as r,Q as o,j as d,m as a}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"设计模式与软件复用","description":"","frontmatter":{"title":"设计模式与软件复用"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法/设计模式与软件复用.md","filePath":"综合知识/架构设计/架构设计方法/设计模式与软件复用.md","lastUpdated":null}'),e={name:"综合知识/架构设计/架构设计方法/设计模式与软件复用.md"};function n(l,t,s,i,h,g){return o(),d("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 设计模式三分类：创建型/结构型/行为型</li><li>[ ] 软件复用：机会复用 vs 系统复用</li><li>[ ] 水平式重用 vs 垂直式重用</li><li>[ ] 复用过程的三个阶段</li><li>[ ] 构件组装与架构失配（三类）</li><li>[ ] 软件产品线核心概念</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、设计模式三分类" tabindex="-1">一、设计模式三分类 <a class="header-anchor" href="#一、设计模式三分类" aria-label="Permalink to &quot;一、设计模式三分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>核心关注</th><th>典型例子</th></tr></thead><tbody><tr><td><strong>创建型</strong></td><td>对象<strong>实例化过程</strong>的抽象</td><td>单例（Singleton）、工厂方法</td></tr><tr><td><strong>结构型</strong></td><td>类或对象的<strong>组合方式</strong></td><td>适配器（Adapter）、桥接（Bridge）</td></tr><tr><td><strong>行为型</strong></td><td>类或对象之间的<strong>交互和职责分配</strong></td><td>策略（Strategy）、观察者（Observer）</td></tr></tbody></table><blockquote><p>🎯 Bridge = 将抽象与实现分离；Strategy = 算法族可互换。飞机模拟系统中飞行行为与起飞行为的解耦 → <strong>Strategy 模式</strong>。</p></blockquote><hr><h3 id="二、软件复用" tabindex="-1">二、软件复用 <a class="header-anchor" href="#二、软件复用" aria-label="Permalink to &quot;二、软件复用&quot;">​</a></h3><p><strong>机会复用 vs 系统复用：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>别名</th><th>特点</th></tr></thead><tbody><tr><td><strong>机会复用</strong></td><td>发现复用</td><td>开发过程中，只要发现有可复用资产就复用</td></tr><tr><td><strong>系统复用</strong></td><td>计划复用</td><td>开发<strong>之前</strong>就进行规划，决定哪些需要复用</td></tr></tbody></table><blockquote><p>🎯 小型敏捷团队更可能频繁发生<strong>机会复用</strong>。大型项目有明确规划时才做<strong>系统复用</strong>。</p></blockquote><p><strong>水平式重用 vs 垂直式重用：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>水平式重用</strong></td><td>跨领域通用，提供基础功能</td><td>标准函数库、通用算法库</td></tr><tr><td><strong>垂直式重用</strong></td><td>面向<strong>特定领域</strong>，包含领域知识</td><td>医学词汇表、网银支付接口</td></tr></tbody></table><p><strong>复用过程的三个阶段：</strong></p><ol><li>构造/获取可复用的软件资产</li><li>管理可复用资产（核心：<strong>构件分类与检索</strong>）</li><li>使用可复用资产</li></ol><blockquote><p>🎯 构件分类方法三大类：关键字分类法、刻面分类法、超文本方法</p></blockquote><hr><h3 id="三、构件组装与架构失配" tabindex="-1">三、构件组装与架构失配 <a class="header-anchor" href="#三、构件组装与架构失配" aria-label="Permalink to &quot;三、构件组装与架构失配&quot;">​</a></h3><p><strong>三类失配：</strong></p><table tabindex="0"><thead><tr><th>失配类型</th><th>产生原因</th></tr></thead><tbody><tr><td><strong>构件失配</strong></td><td>基础设施/控制模型/数据模型的假设冲突</td></tr><tr><td><strong>连接子失配</strong></td><td>交互协议/数据格式的假设冲突</td></tr><tr><td><strong>全局体系结构失配</strong></td><td>系统成分对全局体系结构的假设冲突</td></tr></tbody></table><blockquote><p>⚠️ &quot;构件操作不当引起的失配&quot;不属于构件组装阶段的失配类型。</p></blockquote><hr><h3 id="四、软件产品线" tabindex="-1">四、软件产品线 <a class="header-anchor" href="#四、软件产品线" aria-label="Permalink to &quot;四、软件产品线&quot;">​</a></h3><blockquote><p>软件产品线 = <strong>核心资源 + 产品集合</strong>，特点：过程驱动、特定领域、以技术支持、<strong>以架构为中心</strong>。</p></blockquote><p><strong>实施成功的必要条件：</strong></p><ul><li>对该领域有长期积累的深入经验</li><li>建立好的核心资源库</li><li>创建稳定可靠的产品线架构</li><li>设立独立的核心资源小组 ⚠️（不是必要条件）</li></ul><blockquote><p>将现有多个独立产品整合成产品线 = <strong>用软件产品线替代现有产品集</strong>。</p></blockquote>',27)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
